import RNA, sys
t=open('/tmp/target.txt').read().strip()
warm=open('/tmp/cand.txt').read().strip()
# RNA.inverse_fold(start_seq, target) -> (seq, dist)
# Use multiple restarts
best=None
import random
for r in range(200):
    start=warm if r==0 else None
    try:
        if start:
            seq,dist=RNA.inverse_fold(start,t)
        else:
            seq,dist=RNA.inverse_fold(''.join(random.choice('ACGU') for _ in range(len(t))),t)
    except Exception as e:
        print('err',e); continue
    fc=RNA.fold_compound(seq); m,_=fc.mfe()
    bd=RNA.bp_distance(m,t)
    if best is None or bd<best[0]:
        best=(bd,seq); 
        sys.stdout.write(f'r{r} bd={bd}\n'); sys.stdout.flush()
    if bd==0:
        break
print('BEST',best[0])
if best[0]==0:
    open('/tmp/cand.txt','w').write(best[1]); print('SOLVED'); print(best[1])
EOF
timeout 280 python3 -u /tmp/inv.py 2>&1 | tail -30

